package org.local.donusturucu.qa;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.io.*;import org.json.*;
public class SrtControls extends FileList {
 public void onStart(){Bundle result=new Bundle();try{Intent i=new Intent();i.setClassName("org.local.donusturucu","org.local.donusturucu.MainActivity");i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=startActivitySync(i);long until=System.currentTimeMillis()+60000;while(!(Boolean)get("ready")&&System.currentTimeMillis()<until)Thread.sleep(200);require((Boolean)get("ready"));File root=new File(getTargetContext().getExternalFilesDir(null),"srt-controls-test");root.mkdirs();File audio=new File(root,"Ses.wav");InputStream in=getContext().getAssets().open("short-en.wav");OutputStream out=new FileOutputStream(audio);byte[]buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);in.close();out.close();load(audio,1);JSONArray rows=new JSONArray();
 for(int repeat=1;repeat<=3;repeat++)for(final boolean ku:new boolean[]{false,true}){ui(new Runnable(){public void run(){try{set("ku",ku);set("action","transcribe");call("build",new Class<?>[]{});Spinner sp=(Spinner)get("speechOutput");require(sp.getCount()==2&&sp.getItemAtPosition(0).equals("TXT")&&sp.getItemAtPosition(1).equals("SRT"));sp.setSelection(1);call("buildForm",new Class<?>[]{});require(((Spinner)get("speechOutput")).getSelectedItemPosition()==1);set("busy",true);call("controls",new Class<?>[]{});require(!((Spinner)get("speechOutput")).isEnabled());set("busy",false);call("controls",new Class<?>[]{});require(((Spinner)get("speechOutput")).isEnabled());}catch(Exception e){throw new RuntimeException(e);}}});JSONObject row=new JSONObject();row.put("repeat",repeat);row.put("language",ku?"ku":"tr");row.put("pass",true);rows.put(row);}
 JSONObject report=new JSONObject();report.put("cases",rows.length());report.put("failures",0);report.put("rows",rows);Writer w=new OutputStreamWriter(new FileOutputStream(new File(root,"report.json")),"UTF-8");w.write(report.toString(2));w.close();finish(0,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(1,result);}}
}
